head.script:
scwin.onpageload = function() {
    var json1 = [{
            "col1": 1,
            "col2": "2"
        },
        {
            "col1": "1000",
            "col2": "2000"
        }
    ];
    dataList1.setJSON(json1);
};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    console.log(dataList1.getMatchedJSON("col1", "1", true)); // 정상(return : 0)
};
scwin.trigger2_onclick = function(e) {
    console.log(dataList1.getMatchedJSON("col1", "1", false)); // return : undefined
};
scwin.trigger3_onclick = function(e) {
    console.log(dataList1.getMatchedJSON("col2", "2", true)); // 정상(return : 1)
};
scwin.trigger4_onclick = function(e) {
    console.log(dataList1.getMatchedJSON("col2", "2", false)); // 정상(return : 2)
};
scwin.__checkErrLog = function() {
    return WebSquare.logger.getErrorLog();
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.__checkErrLog() == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //숫자1과 문자1을비교(exactMatch : true)
    //숫자1과 문자1을비교(exactMatch : false)
    //문자2와 문자2 비교(exactMatch : true)
    //문자2와 문자2 비교(exactMatch : false)
    //Function unitTest
    //Create date 12-FEB-2019
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
